def dane(nazwa):
    """Zawartosc wbudowanego pliku albo None, gdy takiego nie ma."""
    tekst = _DANE.get(nazwa)
    if not tekst:
        return None
    return base64.b64decode("".join(tekst))


def sa(nazwa):
    return nazwa in _DANE
